const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define the border region between Craighead and Jackson counties, Arkansas
  // Approximate coordinates for the shared border area
  const geom = ee.Geometry.Polygon([
    [[-90.9, 35.7], [-90.9, 35.9], [-90.6, 35.9], [-90.6, 35.7], [-90.9, 35.7]]
  ]);

  // Define dates
  const date2023 = '2023-04-13';
  const date2025 = '2025-04-13';

  // Function to get water extent for a specific date
  function getWaterExtent(targetDate) {
    const col = ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(geom)
      .filterDate(targetDate, ee.Date(targetDate).advance(1, 'day'))
      .filter(ee.Filter.eq('instrumentMode', 'IW'))
      .select('VV');

    const size = col.size().getInfo();
    if (size === 0) {
      // Try wider date range (±3 days)
      const colWide = ee.ImageCollection('COPERNICUS/S1_GRD')
        .filterBounds(geom)
        .filterDate(ee.Date(targetDate).advance(-3, 'day'), ee.Date(targetDate).advance(4, 'day'))
        .filter(ee.Filter.eq('instrumentMode', 'IW'))
        .select('VV');
      return { col: colWide, size: colWide.size().getInfo() };
    }
    return { col: col, size: size };
  }

  // Get collections for both dates
  const result2023 = getWaterExtent(date2023);
  const result2025 = getWaterExtent(date2025);

  console.log(`2023 Images: ${result2023.size}`);
  console.log(`2025 Images: ${result2025.size}`);

  if (result2023.size === 0 || result2025.size === 0) {
    console.log("No Sentinel-1 data for one or both dates.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Process images - detect water using VV < -15 dB threshold
  const img2023 = result2023.col.mean();
  const img2025 = result2025.col.mean();

  const water2023 = img2023.lt(-15);
  const water2025 = img2025.lt(-15);

  // Calculate water extent (area in square meters)
  const stats2023 = water2023.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geom,
    scale: 3000,
    maxPixels: 1e9
  });

  const stats2025 = water2025.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geom,
    scale: 3000,
    maxPixels: 1e9
  });

  const waterPixels2023 = stats2023.get('VV').getInfo();
  const waterPixels2025 = stats2025.get('VV').getInfo();

  console.log(`2023 Water pixels: ${waterPixels2023}`);
  console.log(`2025 Water pixels: ${waterPixels2025}`);

  if (waterPixels2023 === null || waterPixels2025 === null) {
    console.log("Calculation failed.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Calculate actual water area (pixels * scale^2)
  const area2023 = waterPixels2023 * 9000000; // 3000m * 3000m
  const area2025 = waterPixels2025 * 9000000;

  console.log(`2023 Water extent: ${(area2023 / 1e6).toFixed(2)} km2`);
  console.log(`2025 Water extent: ${(area2025 / 1e6).toFixed(2)} km2`);

  if (area2025 > area2023) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
